import math

def skjkasdkd(lst):
    """Return the sum of the digits of the largest prime number in lst.

    Parameters
    ----------
    lst : list[int]
        List of integers.

    Returns
    -------
    int
        Sum of the digits of the largest prime found, or 0 if no prime exists.
    """
    def is_prime(n: int) -> bool:
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        w = 2
        while i * i <= n:
            if n % i == 0:
                return False
            i += w
            w = 6 - w
        return True

    max_prime = None
    for num in lst:
        if is_prime(num):
            if max_prime is None or num > max_prime:
                max_prime = num

    if max_prime is None:
        return 0
    return sum(int(d) for d in str(max_prime))
